conditionals.code:
$score = 85;

if ($score >= 90) {
    echo 'A';
} elseif ($score >= 80) {
    echo 'B';
} else {
    echo 'C';
}

// Match expression (PHP 8.0+)
$grade = match(true) {
    $score >= 90 => 'A',
    $score >= 80 => 'B',
    default => 'C',
};

for_loop.code:
$items = ['a', 'b', 'c'];

// foreach is preferred for arrays
foreach ($items as $item) {
    echo $item;
}

// Standard for loop
for ($i = 0; $i < count($items); $i++) {
    echo $items[$i];
}

while_loop.code:
$count = 0;

while ($count < 5) {
    echo $count;
    $count++;
}

// Do-while loop
do {
    echo 'Runs at least once';
} while (false);

